const fs = require('fs');
const zlib = require('zlib');
function extract(zipPath, name) {
  const b = fs.readFileSync(zipPath);
  for (let i = 0; i < b.length - 4; i++) {
    if (b.readUInt32LE(i) !== 0x04034b50) continue;
    const method = b.readUInt16LE(i + 8);
    const compSize = b.readUInt32LE(i + 18);
    const uncompSize = b.readUInt32LE(i + 22);
    const nameLen = b.readUInt16LE(i + 26);
    const extraLen = b.readUInt16LE(i + 28);
    const fname = b.subarray(i + 30, i + 30 + nameLen).toString();
    const start = i + 30 + nameLen + extraLen;
    if (fname === name) {
      const data = b.subarray(start, start + compSize);
      const out = method === 0 ? data : zlib.inflateRawSync(data);
      console.log(out.toString());
      return;
    }
    i = start + compSize - 1;
  }
  console.error('not found', name);
}
